        title: String(v.title || '').slice(0, 220),
        url: String(v.url || '').slice(0, 300),
        thumbnail: String(v.thumbnail || v.thumb || '').slice(0, 500),
        duration: v.duration || v.durationSec || null,
        channel: String(v.channel || '').slice(0, 120),
